import { useNavigate, useParams } from 'react-router-dom'
import { rpc } from '../../lib/supabase'
import { money, date, dateTime } from '../../lib/format'
import { Badge, Loading, useLoad } from '../../components/ui'
import { BrandMark } from '../../components/Layout'

// The invoice is generated by the system when an order is approved (by the
// Ops Desk or by the auto-approval rule); nobody types it in. This page shows
// that document so it can be printed or saved as PDF.
export default function InvoiceView() {
  const { id } = useParams()
  const nav = useNavigate()
  const { data, error } = useLoad(() => rpc('invoice_document', { p_invoice: id }), [id])
  if (!data) return <Loading error={error} />
  const { invoice: inv, order, customer, lines, payments, refunds, bank, tax_rate: tax } = data
  const paid = payments.filter((p) => p.status === 'confirmed').reduce((s, p) => s + Number(p.amount), 0)
  const tone = { issued: 'warn', paid: 'good', expired: 'bad', credited: 'muted', cancelled: 'muted' }[inv.status]
  return (
    <>
      <div className="row between no-print">
        <button className="btn" onClick={() => nav(-1)}>← Back</button>
        <button className="btn primary" onClick={() => window.print()}>Print / save as PDF</button>
      </div>
      <article className="card card-pad invoice-doc stack-lg">
        <div className="row between" style={{ alignItems: 'flex-start' }}>
          <div className="stack" style={{ gap: 4 }}>
            <div className="row" style={{ fontWeight: 700, fontSize: 18 }}><BrandMark /> Verity Logistics Ltd</div>
            <div className="muted small">Pay by transfer to {bank.bank}, {bank.account_name}, account {bank.account_no}</div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <h1>Invoice</h1>
            <div className="mono">{inv.invoice_no}</div>
            <Badge tone={tone}>{inv.status}</Badge>
          </div>
        </div>
        <div className="grid-3">
          <div><div className="muted small">Billed to</div><strong>{customer.name}</strong><div className="small">{customer.reg_no}</div><div className="small">{customer.address}</div><div className="small">{customer.contact} · {customer.phone}</div></div>
          <div><div className="muted small">Order</div><strong>{order.order_no}</strong><div className="small">Deliver to {order.address} ({order.region})</div><div className="small">Requested {date(order.requested_date)}</div></div>
          <div><div className="muted small">Issued</div><strong>{dateTime(inv.created_at)}</strong><div className="muted small" style={{ marginTop: 6 }}>Pay by</div><strong>{dateTime(inv.due_at)}</strong></div>
        </div>
        <div className="table-wrap"><table>
          <thead><tr><th>Item</th><th className="num">Qty</th><th className="num">Unit price</th><th className="num">Amount</th></tr></thead>
          <tbody>{lines.map((l, i) => (
            <tr key={i}><td>{l.name}<div className="muted mono">{l.sku}</div></td><td className="num">{l.qty} {l.unit}</td><td className="num">{money(l.unit_price)}</td><td className="num">{money(l.total)}</td></tr>
          ))}</tbody>
        </table></div>
        <div className="totals" style={{ maxWidth: 340, marginLeft: 'auto', width: '100%' }}>
          <div className="line"><span>Subtotal</span><span className="num">{money(inv.subtotal)}</span></div>
          <div className="line"><span>Delivery fee</span><span className="num">{money(inv.delivery_fee)}</span></div>
          <div className="line"><span>Tax ({tax}%)</span><span className="num">{money(inv.tax)}</span></div>
          <div className="line grand"><span>Total</span><span className="num">{money(inv.total)}</span></div>
          {paid > 0 && <div className="line"><span>Paid</span><span className="num">−{money(paid)}</span></div>}
          {refunds.map((r, i) => <div className="line" key={i}><span>Refund {r.credit_note ? `(${r.credit_note})` : '(pending)'}</span><span className="num">{money(r.amount)}</span></div>)}
        </div>
        {payments.length > 0 && (
          <div className="stack">
            <h3>Payments</h3>
            {payments.map((p) => <div key={p.attempt} className="row between small"><span>Attempt {p.attempt} · ref <span className="mono">{p.reference}</span> · {dateTime(p.at)}</span><span>{money(p.amount)} <Badge tone={p.status === 'confirmed' ? 'good' : p.status === 'rejected' ? 'bad' : 'warn'}>{p.status}</Badge></span></div>)}
          </div>
        )}
        <p className="muted small">Generated automatically when the order was approved. Quote {inv.invoice_no} as the transfer narration.</p>
      </article>
    </>
  )
}
